import { readFileSync } from "node:fs";
import { report, totalsByMonth } from "./report.js";
import { parseCsv } from "./csv.js";

const [command, ...args] = process.argv.slice(2);
if (command !== "report" || !args.length) {
  console.error("usage: ledger report [--json] <file.csv>");
  process.exit(2);
}

const isJson = args[0] === "--json";
const file = isJson ? args[1] : args[0];

if (!file) {
  console.error("usage: ledger report [--json] <file.csv>");
  process.exit(2);
}

const text = readFileSync(file, "utf8");

if (isJson) {
  const rows = parseCsv(text);
  const totals = totalsByMonth(rows);
  console.log(JSON.stringify(totals));
} else {
  console.log(report(text));
}

