import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { test } from "node:test";
import { report, totalsByMonth } from "../src/report.js";
import { parseCsv } from "../src/csv.js";

test("totals by month", () => {
  const rows = [
    { date: "2026-03-01", amount: "1.10" },
    { date: "2026-03-20", amount: "2.20" },
    { date: "2026-04-01", amount: "5.00" },
  ];
  assert.deepEqual(totalsByMonth(rows), { "2026-03": 330, "2026-04": 500 });
});
test("march report", () => {
  const text = readFileSync(new URL("../examples/march.csv", import.meta.url), "utf8");
  assert.equal(report(text), "2026-03  USD 125.54\n2026-04  USD 15.20");
});
test("march report as json", () => {
  const text = readFileSync(new URL("../examples/march.csv", import.meta.url), "utf8");
  const rows = parseCsv(text);
  const totals = totalsByMonth(rows);
  assert.deepEqual(totals, { "2026-03": 12554, "2026-04": 1520 });
  assert.equal(JSON.stringify(totals), '{"2026-03":12554,"2026-04":1520}');
});

